class Solution {
private int pos;public String countOfAtoms(String formula){pos=0;Map<String,Integer>counts=parse(formula);StringBuilder out=new StringBuilder();for(String atom:new TreeSet<>(counts.keySet())){out.append(atom);if(counts.get(atom)>1)out.append(counts.get(atom));}return out.toString();}private Map<String,Integer>parse(String s){Map<String,Integer>out=new HashMap<>();while(pos<s.length()&&s.charAt(pos)!=')'){if(s.charAt(pos)=='('){pos++;Map<String,Integer>group=parse(s);pos++;int n=number(s);for(Map.Entry<String,Integer>e:group.entrySet())out.merge(e.getKey(),e.getValue()*n,Integer::sum);}else{int start=pos++;while(pos<s.length()&&Character.isLowerCase(s.charAt(pos)))pos++;String atom=s.substring(start,pos);out.merge(atom,number(s),Integer::sum);}}return out;}private int number(String s){int start=pos,n=0;while(pos<s.length()&&Character.isDigit(s.charAt(pos)))n=n*10+s.charAt(pos++)-'0';return pos==start?1:n;}
}
